<include file="Public:header"/>	<form id="myform" method="post" action="{pigcms{:U('company_audit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="company_id" value="{pigcms{$detail.company_id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">企业名称</th>				<td width="35%">{pigcms{$detail.company_name}</td>			</tr>			<tr>				<th width="15%">法人姓名</th>				<td width="35%">{pigcms{$detail.legal_person_name}</td>			</tr>			<tr>				<th width="15%">手机号</th>				<td width="35%">{pigcms{$detail.phone}</td>			</tr>			<tr>				<th width="15%">身份证号</th>				<td width="35%">{pigcms{$detail.ID_number}</td>			</tr>			<tr>				<th width="15%">地址</th>				<td width="35%">{pigcms{$detail.address}</td>			</tr>			<tr>				<th width="15%">店铺面积</th>				<td width="35%">{pigcms{$detail.acreage}</td>			</tr>			<tr >				<th width="80">营业执照</th>				<td id="product_detail_td">                                   <ul class="image_list" id="product_detail">                    <if condition="$detail.license_pic neq ''">                        <volist name="detail.license_pic" id="vo">                            <li  class="upload_pic_li" style="float:left;list-style:none;"><img src="{pigcms{:file_domain().$vo}" style="width:90px;height:50px;margin-right:5px;" class="view_msg"><br></li>                        </volist>                    </if>                    </ul>				</td>							</tr>			<tr>				<th width="15%">店铺环境照片</th>				<td id="product_detail_td">                    <ul class="image_list1" id="product_detail1">                    <if condition="$detail.company_pic neq ''">                        <volist name="detail.company_pic" id="vo">                            <li  class="upload_pic_li1" style="float:left;list-style:none;"><img src="{pigcms{:file_domain().$vo}" style="width:90px;height:50px;margin-right:5px;" class="view_msg"><br></li>                        </volist>                    </if>                    </ul>				</td>			</tr>			<tr>				<th width="15%">状态</th>				<td width="35%">                         <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 eq $detail['status']">checked="checked"</if> value="1"/> 通过</label>                        <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 neq $detail['status']">checked="checked"</if> value="2" /> 不通过</label>                </td>			</tr>				<tr class="reason">				<th width="15%">原因</th>				<td width="35%">                   <input type="text" class="input fl" name="reason" value="{pigcms{$detail.reason}" placeholder="审核原因"/>                </td>			</tr>					</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form>	<script type="text/javascript">		$('input[name=status]').click(function (argument) {			if ($(this).val()==2) {				$('.reason').show();			}else{				$('.reason').hide();			}		})		$('input[name=status]').trigger('click');	</script><include file="Public:footer"/>